/**
 * Unit tests for AbstractLeastSquaresOptimizer#guessParametersErrors
 */
public class AbstractLeastSquaresOptimizer_guessParametersErrors_TriageGen0Test {

    private TestableOptimizer optimizer;

    /**
     * Concrete implementation of the abstract class for testing purposes.
     */
    private static class TestableOptimizer extends AbstractLeastSquaresOptimizer {
        private int rows;
        private int cols;
        private double chiSquare;
        private double[][] covariances;

        protected TestableOptimizer(int rows, int cols) {
            super();
            this.rows = rows;
            this.cols = cols;
        }

        public void setChiSquare(double chiSquare) {
            this.chiSquare = chiSquare;
        }

        public void setCovariances(double[][] covariances) {
            this.covariances = covariances;
        }

        @Override
        protected VectorialPointValuePair doOptimize() {
            return null; // Not needed for this test
        }

        @Override
        public double getChiSquare() {
            return chiSquare;
        }

        @Override
        public double[][] getCovariances() throws FunctionEvaluationException, OptimizationException {
            return covariances;
        }

        // Mocking access to protected fields if they were accessible, 
        // but since we are in the same package and they are likely private or protected,
        // we simulate the state via setters in the testable subclass.
        // Note: The original code uses 'rows' and 'cols' which must be part of the class state.
        // We assume they are protected/package-private fields in AbstractLeastSquaresOptimizer.
    }

    @Before
    public void setUp() {
        // We use a spy or a subclass because the class is abstract and the method 
        // depends on internal state (rows, cols, getChiSquare, getCovariances).
        // Since we cannot easily set 'rows' and 'cols' via public API if they are private,
        // we assume the testable class can manipulate them.
    }

    @Test(expected = OptimizationException.class)
    public void testGuessParametersErrors_ThrowsExceptionWhenRowsLessThanOrEqualCols() throws Exception {
        // Arrange: rows <= cols (e.g., 2 <= 3)
        optimizer = new TestableOptimizer(2, 3);

        // Act
        optimizer.guessParametersErrors();

        // Assert: Handled by expected exception
    }

    @Test(expected = OptimizationException.class)
    public void testGuessParametersErrors_ThrowsExceptionWhenRowsEqualsCols() throws Exception {
        // Arrange: rows == cols (e.g., 3 == 3)
        optimizer = new TestableOptimizer(3, 3);

        // Act
        optimizer.guessParametersErrors();

        // Assert: Handled by expected exception
    }

    @Test
    public void testGuessParametersErrors_Success() throws Exception {
        // Arrange
        int rows = 10;
        int cols = 2;
        optimizer = new TestableOptimizer(rows, cols);

        double chiSquare = 16.0;
        optimizer.setChiSquare(chiSquare);

        // covar[i][i] values
        // covar[0][0] = 4.0, covar[1][1] = 9.0
        double[][] covar = {
            {4.0, 0.0},
            {0.0, 9.0}
        };
        optimizer.setCovariances(covar);

        // Calculation:
        // c = sqrt(chiSquare / (rows - cols)) = sqrt(16.0 / (10 - 2)) = sqrt(16/8) = sqrt(2)
        // error[0] = sqrt(covar[0][0]) * c = sqrt(4.0) * sqrt(2) = 2 * 1.41421356 = 2.82842712
        // error[1] = sqrt(covar[1][1]) * c = sqrt(9.0) * sqrt(2) = 3 * 1.41421356 = 4.24264068

        double expectedC = Math.sqrt(chiSquare / (rows - cols));
        double[] expectedErrors = new double[cols];
        expectedErrors[0] = Math.sqrt(covar[0][0]) * expectedC;
        expectedErrors[1] = Math.sqrt(covar[1][1]) * expectedC;

        // Act
        double[] actualErrors = optimizer.guessParametersErrors();

        // Assert
        assertArrayEquals(expectedErrors, actualErrors, 1e-10);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testGuessParametersErrors_ThrowsFunctionEvaluationException() throws Exception {
        // Arrange
        optimizer = Mockito.spy(new TestableOptimizer(5, 2));
        optimizer.setChiSquare(10.0);

        // Simulate Exception from getCovariances
        doThrow(new FunctionEvaluationException(new IllegalArgumentException()))
            .when(optimizer).getCovariances();

        // Act
        optimizer.guessParametersErrors();

        // Assert: Handled by expected exception
    }

    @Test(expected = OptimizationException.class)
    public void testGuessParametersErrors_ThrowsOptimizationExceptionFromCovariance() throws Exception {
        // Arrange
        optimizer = Mockito.spy(new TestableOptimizer(5, 2));
        optimizer.setChiSquare(10.0);

        // Simulate Exception from getCovariances
        doThrow(new OptimizationException(new IllegalArgumentException(), "error"))
            .when(optimizer).getCovariances();

        // Act
        optimizer.guessParametersErrors();

        // Assert: Handled by expected exception
    }
}
